def test_input_price_and_privacy_are_pinned(self):
        prep=dict(song='song',shot='shot',source={'sha256':'a'*64},prompt='prompt',estimate={'money':{'amount':'0.70','currency':'USD'}})
        fal.validate_gate(self.gate(),prep,'fixture')
